ALTER TABLE "TrainingAttendance" ADD COLUMN "leavingEarly" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "TrainingCheckIn" ("id" TEXT NOT NULL PRIMARY KEY,"sessionId" TEXT NOT NULL,"blockId" TEXT,"gymnastId" TEXT NOT NULL,"feeling" TEXT,"confidence" TEXT,"recordedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "TrainingCheckIn_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "TrainingSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "TrainingCheckIn_blockId_fkey" FOREIGN KEY ("blockId") REFERENCES "SessionBlock" ("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "TrainingCheckIn_gymnastId_fkey" FOREIGN KEY ("gymnastId") REFERENCES "Gymnast" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "TrainingCheckIn_sessionId_blockId_gymnastId_key" ON "TrainingCheckIn"("sessionId","blockId","gymnastId");
CREATE INDEX "TrainingCheckIn_gymnastId_recordedAt_idx" ON "TrainingCheckIn"("gymnastId","recordedAt");
